/* ================= 页面 ================= */
let page='agent';
const MENU = [
  {g:'工作台'},
  {id:'agent',label:'智能体',ico:'M12 3l1.8 4.2L18 9l-4.2 1.8L12 15l-1.8-4.2L6 9l4.2-1.8z M5 17l.9 2.1L8 20l-2.1.9L5 23l-.9-2.1L2 20l2.1-.9z',roles:['brand','factory','dealer']},
  {id:'tickets',label:'工单处理',ico:'M4 4h16v12H8l-4 4z',cnt:true,roles:['brand','factory','dealer']},
  {g:'产品与知识'},
  {id:'products',label:'产品管理',ico:'M3 7l9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',roles:['brand','factory']},
  {id:'kb',label:'知识库管理',ico:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20 M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z M9 7h7 M9 11h5',roles:['brand','factory']},
  {id:'manuals',label:'说明书生成',ico:'M6 2h9l5 5v15H6z M14 2v6h6 M9 13h6 M9 17h6',roles:['brand','factory']},
  {id:'qr',label:'二维码管理',ico:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h3v3h-3z M19 14h2v2h-2z M17 19h4v2h-4z',roles:['brand']},
  {g:'协作与经营'},
  {id:'orders',label:'订单与协作邀请',ico:'M16 11a4 4 0 1 0-8 0 M3 21a7 7 0 0 1 14 0 M19 8v6 M22 11h-6',roles:['brand','factory','dealer']},
  {id:'analytics',label:'数据分析',ico:'M3 20h18 M6 16V9 M11 16V4 M16 16v-6 M21 16v-3',roles:['brand','factory']},
  {id:'parts',label:'备件与库存',ico:'M12 2l9 5v10l-9 5-9-5V7z M12 12l9-5 M12 12v10 M12 12L3 7',roles:['brand','factory','dealer']},
  {g:'配置'},
  {id:'settings',label:'系统设置',ico:'M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z',roles:['brand']},
];
function icon(d){return `<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${d}"/></svg>`}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),2400)}
function closeAll(){$('#overlay').classList.remove('show');$('#drawer').classList.remove('show');$('#modal').classList.remove('show')}
function openDrawer(html){$('#drawer').innerHTML=html;$('#overlay').classList.add('show');$('#drawer').classList.add('show')}
function openModal(html,wide){$('#modal').innerHTML=`<div class="box${wide?' wide':''}">${html}</div>`;$('#overlay').classList.add('show');$('#modal').classList.add('show')}
function download(name, content, type='text/plain'){ const b=new Blob([content],{type}); const u=URL.createObjectURL(b); const a=document.createElement('a'); a.href=u; a.download=name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(u),2000); }
function decisions(){ const d=[]; for(const t of openTickets()){ if(t.status==='human'||isLate(t)) d.push({k:'ticket',id:t.id,title:`${t.id} ${issueLabel(t,24)}`,sub:isLate(t)?`已超时 ${slaText(t).replace('超时 ','')}，${t.status==='factory'?'工厂未在时限内回复，考虑催促或换人':'等品牌方确认；AI 不会自动越级'}`:(t.reasons.length?`触发规则「${t.reasons.map(r=>({safety:'安全件',refund:'退换货',negative:'负面情绪',b2b:'B端'}[r])).join('、')}」，AI 已暂停自动承诺`:'AI 无法判断，等人工确认')});
    if(t.pending) d.push({k:'ticket',id:t.id,title:`${t.id} 等你确认补发`,sub:`${state.inventory.find(i=>i.part===t.pending.part)?.name||t.pending.part}${t.pending.value?`（约 ${t.pending.value} 美元）`:''}，AI 建议由 ${t.pending.from} 就近补发；客户已被告知等确认`});
    for(const s of (t.shipments||[])) if(s.shippedAt&&!s.tracking&&Date.now()-s.shippedAt>Policy.trackingMs()) d.push({k:'ticket',id:t.id,title:`${t.id} 已发货但没有运单号`,sub:`${s.parts} 已于 ${fmt(s.shippedAt)} 发出，超过 ${Policy.get('shipping.requireTrackingWithinHours')} 小时未回填运单号——品牌与消费者都在等（FWT-61 里这拖了 4 天）`});
    if(t.capa&&t.capa.status==='open'&&new Date(t.capa.due).getTime()-Date.now()<30*DAY) d.push({k:'ticket',id:t.id,title:`${t.id} 质量事件待验证`,sub:`${t.capa.title}（负责人 ${t.capa.owner}，截止 ${t.capa.due}）——口头措施不结案，需工厂提交验证结果`});
    if(t.suggest&&t.status!=='factory'){ const o=state.orders.find(x=>x.id===t.order); const fc=o?factoryContact(o):null; d.push({k:'ticket',id:t.id,title:`AI 建议升级工厂：${t.id}`,sub:`${t.suggest.reason}。接收人：${fc?fc.name+'（'+fc.org+(fc.status==='pending'?'，待接受':'')+'）':'缺少接口人，升级前需先邀请'}`}); }
    if(t.status==='factory'&&t.assignee&&t.assignee.status==='pending') d.push({k:'ticket',id:t.id,title:`${t.id} 指派给了尚未接受邀请的 ${t.assignee.name}`,sub:`${t.assignee.org} 还没接受邀请，这张工单目前没人处理`});
    const ln=lastNonSys(t); if(ln&&ln.who==='fact'&&t.status==='human') d.push({k:'ticket',id:t.id,title:`${t.id} 工厂已回复，待放行`,sub:'确认后 AI 会翻译成客户语言发送'}); }
  for(const m of state.manuals.filter(m=>m.status==='review')) d.push({k:'manual',id:m.id,title:`${m.id} ${Engine.productName(m.product)} ${m.langs.join('/')} 说明书`,sub:`生成完成，合规检查 ${m.checks.filter(c=>c.ok).length}/${m.checks.length} 通过，等待审核`});
  for(const o of ordersWithoutFactory()) d.push({k:'order',id:o.id,title:`${o.id} 缺少工厂接口人`,sub:`${o.factory} 还没有可接升级的联系人，该订单客诉无法升级到工厂`});
  for(const p of state.partners) for(const c of p.contacts) if(c.status==='pending') d.push({k:'partners',id:p.name,title:`${p.name} ${c.name} 尚未接受邀请`,sub:c.defaultAll?`覆盖 ${state.orders.filter(o=>o.factory===p.name||o.dealer===p.name).length} 张订单的协作`:'订单级邀请'});
  return d; }
function renderNav(){ $('#nav').innerHTML=MENU.map(m=>{ if(m.g) return `<div class="nav-group">${m.g}</div>`; const hid=m.roles.includes(role)?'':'hidden'; const cnt=m.cnt?`<span class="cnt num">${openTickets().length}</span>`:''; return `<a href="#${m.id}" class="${page===m.id?'active':''} ${hid}" onclick="go('${m.id}');return false">${icon(m.ico)}<span>${m.label}</span>${cnt}</a>`; }).join('');
  const n=role==='brand'?decisions().length:openTickets().filter(t=>t.status==='factory').length; $('#bellCnt').textContent=n; $('#bellCnt').style.display=n?'grid':'none'; }
function setRole(r){ role=r; $('#avatar').textContent=ROLE[r].av; $('#whoName').textContent=ROLE[r].person; $('#whoOrg').textContent=ROLE[r].name+' · '+ROLE[r].org; $('#roleSel').value=r; const m=MENU.find(x=>x.id===page); if(m&&!m.roles.includes(r)) page='agent'; render(); toast(`已切换为 ${ROLE[r].name}（${ROLE[r].org}）视图`); }
function go(p){ page=p; render(); closeAll(); location.hash=p; }
function render(){ renderNav(); const m=MENU.find(x=>x.id===page); $('#crumb').textContent=m.label; const main=$('#main'); main.className='main'+(page==='agent'?' agent':''); main.innerHTML=PAGES[page](); if(page==='agent') initAgent(); }
const PAGES={};

/* ================= 工单处理 ================= */
const tf={q:'',st:'',ch:'',prod:'',lang:'',pg:0};
function filteredTickets(){ const q=tf.q.trim().toLowerCase(); return visibleTickets().filter(t=>(!tf.st||viewStatus(t)===tf.st)&&(!tf.ch||t.channel===tf.ch)&&(!tf.prod||t.product===tf.prod)&&(!tf.lang||t.cust.lang===tf.lang)&&(!q||[t.id,masked()?'':t.cust.name,masked()?'':t.cust.email,t.sn||'',t.issue,t.product||''].join(' ').toLowerCase().includes(q))); }
const CH={email:'邮件',h5:'扫码H5',manual:'代录入'};
PAGES.tickets=()=>{ const all=visibleTickets(), list=filteredTickets(), PS=20, pages=Math.max(1,Math.ceil(list.length/PS)); tf.pg=Math.min(tf.pg,pages-1); const rows=list.slice(tf.pg*PS,tf.pg*PS+PS);
  const done7=all.filter(t=>t.status==='done'&&t.resolvedAt>Date.now()-7*DAY), ai7=done7.filter(t=>t.resolvedBy==='ai').length; const open=all.filter(t=>t.status!=='done'); const late=open.filter(isLate).length;
  const first=all.filter(t=>t.timeline.length>1&&t.timeline[1].who==='ai').map(t=>t.timeline[1].t-t.timeline[0].t); const avgFirst=first.length?first.reduce((a,b)=>a+b,0)/first.length:0;
  return `
<div class="page-h"><div><h2>工单处理</h2><p>来自邮件和扫码 H5 的客诉统一在这里流转。AI 先处理，拿不准的才找你。</p></div><div class="sp"></div><button class="btn" onclick="exportTickets()">导出 CSV</button>${role==='brand'?`<button class="btn" onclick="openSimEmail()">模拟新邮件进入</button><button class="btn primary" onclick="openNewTicket()">代客户录入</button>`:''}</div>
<div class="grid g4" style="margin-bottom:16px">
  <div class="card kpi"><div class="l">进行中</div><div class="v num">${open.length}</div><div class="d">${open.filter(t=>t.status==='human').length} 条等品牌方 · ${open.filter(t=>t.status==='factory').length} 条在工厂</div></div>
  <div class="card kpi"><div class="l">AI 自行解决率（7 天）</div><div class="v num">${done7.length?Math.round(ai7/done7.length*100):0}%</div><div class="d">${ai7} / ${done7.length} 条已结案工单</div></div>
  <div class="card kpi"><div class="l">平均首次响应</div><div class="v num">${avgFirst?dur(avgFirst):'—'}</div><div class="d">接管邮箱前：19 小时</div></div>
  <div class="card kpi"><div class="l">SLA 超时</div><div class="v num" style="color:${late?'var(--red)':'inherit'}">${late}</div><div class="d">${late?'需人工确认':'全部在时限内'}</div></div>
</div>
<div class="card">
  <div class="filters">
    <input class="input" placeholder="搜索工单号、客户、序列号、问题" style="width:260px" value="${esc(tf.q)}" oninput="tf.q=this.value;tf.pg=0;refreshTable()">
    <select class="select" onchange="tf.st=this.value;tf.pg=0;refreshTable()"><option value="">全部状态</option>${Object.entries(ST).map(([k,v])=>`<option value="${k}" ${tf.st===k?'selected':''}>${v[0]}</option>`).join('')}</select>
    <select class="select" onchange="tf.ch=this.value;tf.pg=0;refreshTable()"><option value="">全部渠道</option>${Object.entries(CH).map(([k,v])=>`<option value="${k}" ${tf.ch===k?'selected':''}>${v}</option>`).join('')}</select>
    <select class="select" onchange="tf.prod=this.value;tf.pg=0;refreshTable()"><option value="">全部产品</option>${state.products.map(p=>`<option ${tf.prod===p.id?'selected':''}>${p.id}</option>`).join('')}</select>
    <select class="select" onchange="tf.lang=this.value;tf.pg=0;refreshTable()"><option value="">全部语种</option>${Object.entries(Engine.LANG_NAME).map(([k,v])=>`<option value="${k}" ${tf.lang===k?'selected':''}>${v}</option>`).join('')}</select>
    <div class="sp" style="flex:1"></div><span class="muted small" id="tcount">共 ${list.length} 条</span>
  </div>
  <div id="ttable">${ticketTable(rows,list.length,pages)}</div>
</div>`};
function ticketTable(rows,total,pages){ return `<table class="tb"><tr><th>工单</th><th>客户</th><th>产品 / 序列号</th><th>问题</th><th>渠道</th><th>状态</th><th>SLA</th><th>更新</th></tr>
  ${rows.length?rows.map(t=>`<tr class="trow" onclick="openTicket('${t.id}')"><td class="num">${t.id}</td><td>${custLabel(t)}<div class="sub">${custSub(t)}</div></td><td>${t.product?Engine.productName(t.product):'<span class="muted">未识别</span>'}<div class="sub num">${t.sn||'—'}</div></td><td style="max-width:300px">${issueLabel(t)}</td><td>${CH[t.channel]}</td><td>${tagOf(t)}</td><td class="sla ${isLate(t)?'late':''}">${slaText(t)}</td><td class="muted">${fmt(t.updatedAt)}</td></tr>`).join(''):`<tr><td colspan="8"><div class="empty"><b>没有符合条件的工单</b>换个筛选条件，或点"模拟新邮件进入"看一封客诉是怎么被处理的</div></td></tr>`}</table>
  ${pages>1?`<div class="pager">${Array.from({length:pages},(_,i)=>`<button class="${i===tf.pg?'on':''}" onclick="tf.pg=${i};refreshTable()">${i+1}</button>`).join('')}<span class="muted small">每页 20 条</span></div>`:''}`; }
function refreshTable(){ const list=filteredTickets(), PS=20, pages=Math.max(1,Math.ceil(list.length/PS)); tf.pg=Math.min(tf.pg,pages-1); $('#ttable').innerHTML=ticketTable(list.slice(tf.pg*PS,tf.pg*PS+PS),list.length,pages); $('#tcount').textContent=`共 ${list.length} 条`; }
function exportTickets(){ const rows=[['工单','创建时间','客户','邮箱','语言','产品','序列号','订单','分销商','渠道','问题','知识库','置信度','状态','处理方','评分']]; for(const t of filteredTickets()) rows.push([t.id,new Date(t.createdAt).toISOString(),masked()?'—':t.cust.name,masked()?'—':t.cust.email,t.cust.lang,t.product||'',t.sn||'',t.order||'',t.dealer||'',CH[t.channel],t.issue,t.kbId||'',t.confidence??'',ST[t.status][0],t.resolvedBy||'',t.rating??'']); download(`工单导出_${new Date().toISOString().slice(0,10)}.csv`,'﻿'+rows.map(r=>r.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n'),'text/csv'); toast(`已导出 ${rows.length-1} 条`); }

const WHO={cust:'客户',ai:'售后智能体',human:'品牌方售后',fact:'工厂',dealer:'分销商',sys:'系统'};
const REGION={en:'英语区',de:'德语区',es:'西班牙语区',fr:'法语区',sv:'瑞典',it:'意大利',zh:'中国'};
function masked(){ return role==='factory'; }
function lastNonSys(t){ for(let i=t.timeline.length-1;i>=0;i--) if(t.timeline[i].who!=='sys') return t.timeline[i]; return null; }
function custLabel(t){ return masked()?`客户（${REGION[t.cust.lang]||t.cust.lang}）`:esc(t.cust.name); }
function custSub(t){ return masked()?`${Engine.LANG_NAME[t.cust.lang]||t.cust.lang} · 身份由品牌方保管`:`${Engine.LANG_NAME[t.cust.lang]||t.cust.lang} · ${esc(t.cust.email)}`; }
// 工厂角色看不到客户原文：问题列显示知识条目名或 AI 摘要
function issueLabel(t,max){ const kb=Engine.KB.find(k=>k.id===t.kbId); let s; if(masked()){ const c=t.timeline.find(e=>e.who==='cust'); s=kb?kb.cat.zh:(c&&c.tr)||'客户描述由品牌方保管'; } else s=t.issue||(kb?kb.cat.zh:''); if(max&&s.length>max) s=s.slice(0,max)+'…'; return esc(s); }
function maskText(e){ if(!masked()) return e.text; if(e.who==='cust') return e.tr?`[AI 摘要] ${e.tr}`:'[客户原文由品牌方保管]'; if(e.who==='ai'&&e.tr) return `[发给客户的回复，摘要] ${e.tr}`; return e.text; }
function openTicket(id){ const t=tById(id); if(!t) return; const kb=Engine.KB.find(k=>k.id===t.kbId); const o=state.orders.find(x=>x.id===t.order); const fc=o?factoryContact(o):null; const a=Engine.assess({text:t.timeline.filter(e=>e.who==='cust').map(e=>e.text).join('\n'),product:t.product,serial:t.sn?{valid:true}:null,photos:t.photos,email:t.cust.email,settings:state.settings});
  const last=t.timeline[t.timeline.length-1]; const ln=lastNonSys(t); const factoryReplyPending=ln&&ln.who==='fact'&&t.status==='human';
  let suggest=''; if(t.status!=='done'){ if(masked()) suggest=''; else if(factoryReplyPending) suggest=ln.text; else if(t.status==='human'||t.status==='factory'||isLate(t)) suggest=kb?kb.reply[t.cust.lang]?kb.reply[t.cust.lang](ctxFor(t)):kb.reply.en(ctxFor(t)):Engine.compose({action:'ask'},ctxFor(t)); else suggest=Engine.compose(a,ctxFor(t)); }
  const canAct=t.status!=='done'; const members=o?orderMembers(o).filter(m=>m.role!=='b'):[]; const collab=t.collab||[];
  openDrawer(`
  <div class="drawer-h"><h3 class="num">${t.id}</h3>${tagOf(t)}<span class="muted small">${CH[t.channel]} · ${Engine.LANG_NAME[t.cust.lang]||t.cust.lang} · 创建于 ${fmt(t.createdAt)}</span><div class="sp" style="flex:1"></div><button class="x" onclick="closeAll()">×</button></div>
  <div class="drawer-b">
    <div class="grid g2" style="margin-bottom:16px">
      <div class="card card-b" style="padding:14px 16px"><div class="muted small">设备（${t.sn?'AI 从标签 / 来信识别':'未提供序列号'}）</div><div style="font-weight:600;margin-top:4px">${t.product?Engine.productName(t.product):'未识别'}</div><div class="num muted small">${t.sn?`序列号 ${t.sn} · 批次 ${t.batch}`:'—'}</div><div class="small" style="margin-top:6px">${o?`订单 <a onclick="go('orders')">${o.id}</a> · 分销商 ${o.dealer} · 工厂 ${o.factory}`:'未匹配到订单（无序列号，不猜）'}</div>${!t.sn&&role==='brand'&&canAct?`<div class="row" style="margin-top:8px;gap:6px"><input class="input" id="snFix" placeholder="补序列号，如 SM9-24B-00931" style="flex:1;font-size:12px;padding:4px 8px"><button class="btn sm" onclick="setSerial('${t.id}')">校验并写入</button></div>`:''}</div>
      <div class="card card-b" style="padding:14px 16px"><div class="muted small">客户${masked()?' · 已脱敏':''}</div><div style="font-weight:600;margin-top:4px">${custLabel(t)}</div><div class="muted small">${custSub(t)}</div><div class="small" style="margin-top:6px">${masked()?`照片 ${t.photos}`:`历史工单 ${state.tickets.filter(x=>x.cust.email===t.cust.email).length} · 照片 ${t.photos} · ${t.rating?`评分 ${t.rating}`:'未评分'}`}</div></div>
    </div>
    <div class="card card-b" style="padding:12px 16px;margin-bottom:16px;background:#FAFBFC"><div class="row" style="flex-wrap:wrap;gap:8px"><span class="tag ai">置信度 ${t.confidence??'—'}%</span>${kb?`<span class="tag grey">知识库：${kb.cat.zh}</span>`:'<span class="tag grey">未匹配知识库</span>'}${t.reasons.map(r=>`<span class="tag amber">${({safety:'安全件',refund:'退换货',negative:'负面情绪',b2b:'B端客户'})[r]}</span>`).join('')}${t.asks?`<span class="tag grey">已追问 ${t.asks} 轮</span>`:''}${t.assignee?`<span class="tag violet">工厂接口人 ${esc(t.assignee.name)}${t.assignee.status==='pending'?' · 待接受':''}</span>`:''}</div>
      <div class="row" style="flex-wrap:wrap;gap:6px;margin-top:10px;align-items:center"><span class="muted small">协作：</span>${members.map(m=>memberChip(m)).join('')}${collab.map(c=>memberChip(c,' · 工程师')).join('')}${!members.length&&!collab.length?'<span class="muted small">无</span>':''}${role==='factory'&&canAct?`<button class="btn sm ghost" onclick="openInviteEngineer('${t.id}')">＋ 邀请内部工程师</button>`:''}${role==='brand'&&(collab.some(c=>c.status==='pending')||(t.assignee&&t.assignee.status==='pending'))?`<button class="btn sm ghost" onclick="${t.assignee&&t.assignee.status==='pending'?`acceptOne('${esc(t.assignee.email)}')`:`acceptOne('${esc(collab.find(c=>c.status==='pending').email)}')`};openTicket('${t.id}')">模拟对方接受</button>`:''}</div></div>
    ${isLate(t)?`<div class="notice" style="margin-bottom:16px"><span>⚠</span><div><b>已超出 ${t.status==='human'?Policy.slaHours('l1'):Policy.slaHours('l2')} 小时 SLA。</b>客户已等待 ${dur(Date.now()-t.statusSince)}。${t.status==='factory'?'工厂未按时回复；AI 不会自动改派，你可以催促或换接口人。':'AI 不会自动越级，确认处置后会用客户语言回复。'}</div></div>`:''}
    ${t.suggest&&t.status!=='factory'&&role==='brand'?`<div class="notice" style="margin-bottom:16px;background:var(--violet-soft);border-color:#CFCAF3;color:#3B3391"><span>→</span><div><b>AI 建议升级到工厂：</b>${esc(t.suggest.reason)}。接收人：${fc?`${esc(fc.name)}（${esc(fc.org)}${fc.status==='pending'?'，尚未接受邀请':''}）`:`<span style="color:var(--red)">缺少接口人</span>`}<div class="row" style="margin-top:8px"><button class="btn sm primary" onclick="escalate('${t.id}')">${fc?'按建议升级':'邀请接口人并升级'}</button><button class="btn sm" onclick="dismissSuggest('${t.id}')">忽略建议</button></div></div></div>`:''}
    ${t.pending&&!masked()?`<div class="notice" style="margin-bottom:16px;background:var(--ai-soft);border-color:#BFE3DA;color:var(--ai-ink)"><span>→</span><div><b>AI 建议由 ${t.pending.from} 就近补发 ${state.inventory.find(i=>i.part===t.pending.part)?.name||t.pending.part}${t.pending.value?`（约 ${t.pending.value} 美元${t.pending.value>Policy.get('shipping.autoCommitLimitUsd')?'，超出 AI 自行承诺额度':''}）`:''}。</b>库存 ${state.inventory.find(i=>i.part===t.pending.part)?.qty??'—'}。客户已被告知"${Policy.get('routing.l1.hours')} 小时内确认"。${role==='brand'?`<div class="row" style="margin-top:8px"><button class="btn sm primary" onclick="confirmShip('${t.id}')">确认补发并通知客户</button><button class="btn sm" onclick="declineShip('${t.id}')">不补发，改为人工处理</button></div>`:''}</div></div>`:''}
    ${factoryReplyPending&&role==='brand'?`<div class="notice" style="margin-bottom:16px;background:var(--violet-soft);border-color:#CFCAF3;color:#3B3391"><span>↩</span><div><b>工厂已回复，等你放行。</b>下方是工厂原话，确认或修改后 AI 会翻译成 ${Engine.LANG_NAME[t.cust.lang]} 发给客户。</div></div>`:''}
    ${(t.issues||[]).length?`<div class="card" style="margin-bottom:16px"><div class="card-h"><h3>子问题（一封来信拆成 ${t.issues.length} 条）</h3><div class="sp"></div><span class="muted small">各自闭环，互不阻塞</span></div><div class="card-b"><div class="issues">${t.issues.map((is,i)=>{ const cls={open:'amber',guiding:'amber',waitfact:'violet',shipped:'green',closed:'green',done:'green'}[is.status]||'grey'; const lbl={open:'处理中',guiding:'指导中',waitfact:'等工厂',shipped:'已发运',closed:'已结案',done:'已完成'}[is.status]||is.status; return `<div class="issue"><div class="issue-h"><span class="tag ${cls}">${lbl}</span><b>${esc(is.title)}</b><span class="muted small" style="margin-left:auto">${is.owner==='factory'?'工厂':'品牌'}</span></div>${(is.checklist||[]).length?`<ul class="ckl">${is.checklist.map((c,j)=>`<li class="${c.done?'ok':''}"><span class="ck" onclick="${canAct&&role==='brand'?`issueDone('${t.id}',${i},${j})`:''}">${c.done?'✓':'○'}</span>${esc(c.q)}${c.ans?`<span class="muted small"> — ${esc(c.ans)}</span>`:''}</li>`).join('')}</ul>`:''}${is.note?`<div class="muted small" style="margin-top:6px">${esc(is.note)}</div>`:''}</div>`; }).join('')}</div></div></div>`:''}
    ${(t.shipments||[]).length?`<div class="card" style="margin-bottom:16px"><div class="card-h"><h3>寄件与运单</h3><div class="sp"></div><span class="muted small">发货当天应自动推送品牌与消费者</span></div><div class="card-b">${t.shipments.map((s,i)=>`<div class="row" style="flex-wrap:wrap;gap:8px;padding:8px 0;border-bottom:1px dashed var(--line);align-items:center">
      <b>${esc(s.parts)}</b><span class="muted small">${esc(s.to)} · ${esc(s.addr)}</span><span class="tag grey">${esc(s.method)}</span>
      <span class="tag ${s.shippedAt?'green':'amber'}">${s.shippedAt?'已发 '+fmt(s.shippedAt):'未发货'}</span><span class="tag grey">承诺 ${s.promisedAt?fmt(s.promisedAt):'—'}</span>
      ${s.tracking?`<span class="tag ai">运单 ${esc(s.tracking)}</span>${!s.trackingAt?`<button class="btn sm" onclick="shipArrived('${t.id}',${i})">确认签收</button>`:''}`:s.shippedAt?`<input class="input" id="trk${i}" placeholder="补填运单号" style="width:150px;font-size:12px;padding:3px 8px"><button class="btn sm primary" onclick="shipTrack('${t.id}',${i})">回填</button><span class="muted small" style="color:var(--red)">超 ${Policy.get('shipping.requireTrackingWithinHours')}h 未回填</span>`:`<button class="btn sm" onclick="shipSend('${t.id}',${i})">登记发货</button>`}
    </div>`).join('')}</div></div>`:''}
    ${t.capa?`<div class="card" style="margin-bottom:16px"><div class="card-h"><h3>质量事件（CAPA）</h3><div class="sp"></div><span class="tag ${t.capa.status==='open'?'amber':'green'}">${t.capa.status==='open'?'跟进中':'已验证'}</span></div><div class="card-b"><b>${esc(t.capa.title)}</b><div class="muted small">负责人 ${esc(t.capa.owner)} · 截止 ${esc(t.capa.due)}${t.capa.note?` · ${esc(t.capa.note)}`:''}</div>${canAct&&role==='brand'&&t.capa.status==='open'?`<div class="row" style="margin-top:8px"><button class="btn sm" onclick="capaDone('${t.id}')">工厂已提交验证结果</button></div>`:''}</div></div>`:''}
    <div class="card"><div class="card-h"><h3>对话时间线</h3><div class="sp"></div><span class="muted small">${masked()?'客户原文已隐藏，显示 AI 摘要':'原文 + 系统摘要'}</span></div>
    <div class="card-b"><ul class="tl">${t.timeline.map(e=>`<li class="${e.who}"><div class="t">${fmt(e.t)}</div><div><div class="who">${WHO[e.who]}${e.who==='ai'&&t.status!=='done'&&e===last?' <span class="tag ai">最新</span>':''}</div><div class="msg">${esc(maskText(e))}</div>${e.tr&&!masked()?`<div class="tr">${esc(e.tr)}</div>`:''}</div></li>`).join('')}</ul></div></div>
    ${canAct?`<div class="card" style="margin-top:16px"><div class="card-h"><h3>${role==='factory'?'回复给品牌方':factoryReplyPending?'放行工厂回复':(t.status==='human'||t.status==='factory'?'AI 起草的回复（等你确认）':'AI 的下一步')}</h3><div class="sp"></div><span class="muted small">${role==='factory'?'品牌方放行后由 AI 翻译发给客户':role==='dealer'?'只记录到时间线，品牌方可见':`将以 ${Engine.LANG_NAME[t.cust.lang]||t.cust.lang} 发送`}</span></div>
    <div class="card-b"><textarea class="input" id="replyBox" style="width:100%;min-height:110px" placeholder="${role==='factory'?'用中文写即可，例如：同批次抽检 5 台未复现，判定为个案，按保修更换。':''}">${esc(suggest)}</textarea>
      <div class="row" style="margin-top:10px;flex-wrap:wrap"><button class="btn primary" onclick="sendReply('${t.id}')">${role==='factory'?'发送给品牌方':role==='dealer'?'记录门店备注':factoryReplyPending?'放行并发送给客户':'发送给客户'}</button>${role==='factory'?'':`<span class="muted small" title="正式版：LLM 按条目步骤与客户语气改写草稿；原型不模拟">换一种说法（正式版由 LLM 改写）</span>`}<div class="sp" style="flex:1"></div>${role==='brand'&&t.status!=='factory'?`<button class="btn" onclick="escalate('${t.id}')">升级给工厂${fc?'':'（需先邀请）'}</button>`:''}${role==='brand'&&t.status==='factory'?`<button class="btn" onclick="recall('${t.id}')">撤回到品牌方</button>`:''}${role==='factory'?'<span class="muted small">关单由品牌方确认</span>':`<button class="btn" onclick="resolve('${t.id}')">${role==='dealer'?'门店已处理':'标记已解决'}</button>`}</div>
      ${role==='brand'?`<div class="row" style="margin-top:14px;padding-top:12px;border-top:1px dashed var(--line)"><input class="input" id="custSim" style="flex:1" placeholder="模拟客户回信（用客户语言输入，看 AI 怎么接）"><button class="btn sm" onclick="simCustomer('${t.id}')">客户回信</button></div>`:''}
    </div></div>`:`<div class="row" style="margin-top:16px;justify-content:flex-end"><span class="muted small">由 ${({ai:'AI',brand:'品牌方',factory:'工厂',dealer:'分销商'})[t.resolvedBy]||'—'} 解决 · 用时 ${dur(t.resolvedAt-t.createdAt)}</span>${role==='brand'?`<button class="btn" onclick="reopen('${t.id}')">重新打开</button>`:''}</div>`}
  </div>`); }
function whoByRole(){ return role==='brand'?'human':role==='factory'?'fact':'dealer'; }
function sendReply(id){ const t=tById(id); const text=$('#replyBox').value.trim(); if(!text){ toast('回复内容为空'); return; }
  if(role==='factory'){ addEntry(t,'fact',text,`工厂接口人 ${ROLE.factory.person} 回复，待品牌方放行`); setStatus(t,'human'); addEntry(t,'sys','工厂已回复。品牌方放行后由 AI 翻译成客户语言发送。'); openTicket(id); render(); toast('已发送给品牌方，等待放行'); return; }
  if(role==='dealer'){ addEntry(t,'dealer',text,'分销商备注'); openTicket(id); render(); toast('已记录到时间线'); return; }
  const ln=lastNonSys(t); const fromFactory=ln&&ln.who==='fact';
  addEntry(t,'human',text,fromFactory?`品牌方放行工厂回复，由 ${ROLE[role].person} 确认`:`由 ${ROLE[role].person} 确认发送`);
  // 人工回复里出现零件号或"补发/寄送"字样 → 视为承诺寄件，扣库存并清掉待确认项（与 AI 承诺同一口径）
  const partHit=state.inventory.find(i=>text.toUpperCase().includes(i.part.toUpperCase()))||(t.pending&&/补发|寄|ship|send|versand|schick|envi|expédi/i.test(text)?state.inventory.find(i=>i.part===t.pending.part):null);
  if(partHit&&!t.shipped){ const inv=shipPart(partHit.part); t.shipped=true; t.pending=null; addEntry(t,'sys',`人工回复中承诺寄送 ${inv.name}（${inv.part}），${inv.loc} 库存扣减至 ${inv.qty}。`); }
  addEntry(t,'ai',`[${Engine.LANG_NAME[t.cust.lang]||t.cust.lang}] ${text}`,fromFactory?'AI 已将工厂回复翻译为客户语言发送':'AI 已翻译并发送');
  if(t.status==='human'||t.status==='factory'){ setStatus(t,'ai'); addEntry(t,'sys','已用客户语言发送，AI 继续跟进客户回复。'); }
  openTicket(id); render(); toast('已发送，并抄送品牌方售后邮箱'); }
function escalate(id){ if(role!=='brand'){ toast('只有品牌方可以把工单升级给工厂'); return; } const t=tById(id); const o=state.orders.find(x=>x.id===t.order);
  if(!o){ toast('工单未匹配到订单，无法确定工厂接口人；请先补序列号'); return; }
  const fc=factoryContact(o);
  if(!fc){ openInvite(o.id,o.factory,t.id); return; }
  setStatus(t,'factory'); t.assignee={name:fc.name,email:fc.email,org:fc.org,status:fc.status}; t.suggest=null;
  if(fc.status==='active') addEntry(t,'sys',`已指派工厂接口人 ${fc.name}（${fc.org}），邮件通知已发送（二级，${Policy.slaHours('l2')} 小时）。附带序列号、批次、照片与 AI 摘要；客户身份不对工厂展示。`);
  else addEntry(t,'sys',`已指派 ${fc.name}（${fc.org}），但对方尚未接受邀请，已再次发送邀请邮件。接受前这张工单不会被处理，已列入"需要你的决定"。`);
  openTicket(id); render(); toast(fc.status==='active'?`已升级给 ${fc.name}`:`已升级，但 ${fc.name} 还没接受邀请`); }
function recall(id){ const t=tById(id); setStatus(t,'human'); addEntry(t,'sys',`品牌方撤回工单，${t.assignee?t.assignee.name:'工厂'}不再处理。`); t.assignee=null; openTicket(id); render(); }
function dismissSuggest(id){ const t=tById(id); addEntry(t,'sys',`品牌方忽略了 AI 的升级建议（${t.suggest.reason}）。`); t.suggest=null; openTicket(id); render(); }
function resolve(id){ if(role==='factory'){ toast('工厂不能直接关闭工单：请把结论回复给品牌方，由品牌方放行并关单'); return; } const t=tById(id); setStatus(t,'done',role==='brand'?'brand':role); addEntry(t,role==='dealer'?'dealer':'sys',role==='dealer'?'分销商门店已就近处理，同步回品牌方和工厂。':`工单由${ROLE[role].name}关闭。`); if(role==='dealer') addEntry(t,'sys','工单已关闭（分销商处理）。'); closeAll(); render(); toast(`${id} 已标记为已解决`); }
function reopen(id){ if(role!=='brand'){ toast('只有品牌方可以重新打开工单'); return; } const t=tById(id); t.status='human'; t.statusSince=Date.now(); t.resolvedAt=null; t.resolvedBy=null; addEntry(t,'sys','工单重新打开，等待品牌方售后。'); openTicket(id); render(); }
function confirmShip(id){ if(role!=='brand'){ toast('补发由品牌方确认'); return; } const t=tById(id); const inv=shipPart(t.pending.part); const kb=Engine.KB.find(k=>k.id===t.kbId); const c=ctxFor(t); addEntry(t,'human',`确认由 ${t.pending.from} 补发 ${inv?inv.name:t.pending.part}，2 到 4 个工作日内寄出。${inv?`库存扣减至 ${inv.qty}。`:''}`); const lang=['en','de','es','fr','sv','zh'].includes(c.lang)?c.lang:'en'; addEntry(t,'ai',Engine.shipLine(lang,true,{dealer:c.dealer,city:c.city}),`已用客户语言通知：${kb?kb.partName.zh:t.pending.part} 将从 ${t.pending.from} 寄出`); t.pending=null; t.shipped=true; touch(t); openTicket(id); render(); toast('已通知客户补发'); }
function declineShip(id){ const t=tById(id); addEntry(t,'human',`品牌方未确认补发 ${t.pending.part}，转人工跟进。`); t.pending=null; setStatus(t,'human'); addEntry(t,'sys',`已转 ${Policy.get('routing.l1.name')}（品牌方售后，一级）。`); openTicket(id); render(); toast('已转人工处理'); }
/* ---- 子问题核销 / 运单 / CAPA（FWT-61 引入；改的是工单上的结构化字段，时间线只做记录） ---- */
function issueDone(id,i,j){ const t=tById(id); const it=t.issues[i]; if(!it||!it.checklist[j]) return; it.checklist[j].done=!it.checklist[j].done; if(it.checklist.every(c=>c.done)&&['open','waitfact','guiding'].includes(it.status)) it.status='closed'; addEntry(t,'sys',`子问题「${it.title}」核销项${it.checklist[j].done?'完成':'取消'}：${it.checklist[j].q}`); openTicket(id); render(); }
function capaDone(id){ const t=tById(id); if(!t.capa) return; t.capa.status='verified'; t.capa.verifiedAt=Date.now(); addEntry(t,'sys',`质量事件「${t.capa.title}」验证通过，关闭 CAPA。`); openTicket(id); render(); toast('CAPA 已关闭'); }
function shipSend(id,i){ const t=tById(id); const s=t.shipments[i]; if(!s) return; s.shippedAt=Date.now(); addEntry(t,'sys',`登记发货：${s.parts} → ${s.to}（${s.method}）。运单号须在 24 小时内回填。`); openTicket(id); render(); }
function shipTrack(id,i){ const t=tById(id); const s=t.shipments[i]; if(!s) return; const v=($('#trk'+i).value||'').trim(); if(!v){ toast('运单号为空'); return; } s.tracking=v; s.trackingAt=Date.now(); addEntry(t,'sys',`运单号 ${v} 已回填并推送给品牌与消费者（FWT-61 里这拖了 4 天）。`); openTicket(id); render(); toast('运单号已推送'); }
function shipArrived(id,i){ const t=tById(id); const s=t.shipments[i]; if(!s) return; s.arrivedAt=Date.now(); addEntry(t,'sys',`${s.to} 确认签收（${s.parts}）。`); openTicket(id); render(); }
function simCustomer(id){ const t=tById(id); const text=$('#custSim').value.trim(); if(!text) return; const r=runPipeline({from:t.cust.email,name:t.cust.name,lang:t.cust.lang,subject:'',body:text,photos:/photo|video|foto|bild|照片|视频/i.test(text)?1:0}); openTicket(r.ticket.id); render(); toast(r.steps.at(-2).text); }
// 品牌方给没有序列号的工单补录序列号：校验格式与型号，写入批次 / 订单 / 分销商，之后才能升级给对应工厂
function setSerial(id){ const t=tById(id); const v=$('#snFix').value.trim().toUpperCase(); const p=Engine.parseSerial(v); if(!p){ toast('序列号格式不对，应为 AA0-00A-00000'); return; } if(!p.valid){ toast(`前缀 ${v.slice(0,3)} 不对应任何型号`); return; } if(t.product&&p.product!==t.product){ toast(`这个序列号属于 ${Engine.productName(p.product)}，与工单识别的 ${Engine.productName(t.product)} 不一致`); return; } t.sn=p.sn; t.batch=p.batch; t.product=t.product||p.product; if(p.order){ t.order=p.order; t.dealer=p.dealer; } addEntry(t,'sys',`品牌方补录序列号 ${p.sn}（批次 ${p.batch}）${p.order?`，匹配订单 ${p.order} · 分销商 ${p.dealer} · 工厂 ${p.factory}${p.warrantyUntil?' · 保修至 '+p.warrantyUntil:''}`:'，批次不在任何订单里，订单待定'}。`); if(t.kbId&&p.order){ const c=batchCluster(state.tickets,t.kbId,t.product,t.batch,t); if(c.hot&&t.status!=='factory') t.suggest={type:'factory',reason:clusterReason({...c,same:c.same+1}),at:Date.now()}; } openTicket(id); render(); toast(p.order?`已写入，订单 ${p.order}`:'已写入，但没有匹配到订单'); }
function openNewTicket(){ openModal(`<div class="drawer-h"><h3>代客户录入客诉</h3><div class="sp" style="flex:1"></div><button class="x" onclick="closeAll()">×</button></div><div class="drawer-b">
<p class="muted small" style="margin-top:0">用于电话或社交媒体收到的客诉。录入后走和邮件一样的流水线，AI 会用客户语言联系对方。</p>
<div class="grid g2"><div class="field"><label>客户姓名</label><input class="input" id="nt_name" placeholder="Mark Reynolds"></div><div class="field"><label>客户邮箱</label><input class="input" id="nt_mail" placeholder="customer@example.com"></div></div>
<div class="field"><label>序列号（可选，标签上的 S/N）</label><input class="input" id="nt_sn" placeholder="SM9-24B-00931"></div>
<div class="field"><label>客户原话（任何语言）</label><textarea class="input" id="nt_body" rows="3" placeholder="例如：The cable is fraying near the top pulley"></textarea></div>
<div class="check"><button class="switch" id="nt_photo" onclick="this.classList.toggle('on')"></button><div>客户提供了照片或视频</div></div>
<div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn" onclick="closeAll()">取消</button><button class="btn primary" onclick="createManual()">创建并处理</button></div></div>`); }
function createManual(){ const mail=$('#nt_mail').value.trim(), body=$('#nt_body').value.trim(); if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(mail)){ toast('请输入有效邮箱'); return; } if(!body){ toast('请输入客户原话'); return; } const r=runPipeline({from:mail,name:$('#nt_name').value.trim()||undefined,subject:'',body,sn:$('#nt_sn').value.trim()||undefined,channel:'manual',photos:$('#nt_photo').classList.contains('on')?1:0}); closeAll(); showPipeline(r); }

