function policySet(path,val){ try{ const r=Policy.set(path,val); render(); if(r.changed) toast(`${Policy.label(path)}：${r.from} → ${r.to}`); }catch(e){ toast(e.message); render(); } }
function policyReset(path){ if(path && !confirm('把「'+Policy.label(path)+'」恢复为出厂值？')) return; Policy.reset(path); save(); render(); toast(path?'已恢复出厂值':'全部政策已恢复出厂值'); }
function policyReplay(path){
  const v=Policy.get(path); const all=state.tickets.filter(t=>t.createdAt>Date.now()-30*DAY&&t.confidence!=null);
  const hit=n=>all.filter(t=>t.confidence>=n&&!t.reasons.length).length;
  const thr=Policy.get('autoReply.threshold'), band=Policy.get('autoReply.askBand');
  const reply=all.length?Math.round(hit(thr)/all.length*100):0, ask=all.length?Math.round((all.filter(t=>t.confidence>=thr-band&&t.confidence<thr&&!t.reasons.length).length)/all.length*100):0;
  return `<div class="notice" style="margin-top:10px"><span>i</span><div><b>按当前政策回放近 30 天 ${all.length} 条工单：</b>AI 直接回复 ${reply}%，先追问 ${ask}%，直接转人工 ${Math.max(0,100-reply-ask)}%（含 ${all.filter(t=>t.reasons.length).length} 条触发硬规则）。10 天内承诺寄件在 ${
    state.tickets.filter(t=>t.createdAt>Date.now()-30*DAY&&t.kbId&&!t.reasons.length).reduce((n,t)=>{ const kb=Engine.KB.find(k=>k.id===t.kbId); return n+(kb&&kb.part&&kb.partValue<=Policy.get('shipping.autoCommitLimitUsd')?1:0); },0)} 条上会被 AI 自动承诺。</div></div>`;
}
// 政策面板：分四组渲染，数值项带范围、说明、锁定标记；变更记录可追溯
function policyPanel(){
  const v=Policy.view(); const row=(path,extra)=>policyRow(path,extra);
  const grp=(title,desc,body)=>`<div class="field" style="margin-bottom:4px"><label style="font-size:15px">${title}</label><div class="muted small" style="margin:-2px 0 8px">${desc}</div>${body}</div>`;
  const diffs=Policy.diff();
  const logRows=Policy.log().slice().reverse().slice(0,12);
  return `
<div class="notice" style="margin-bottom:14px"><span>i</span><div><b>这一页就是产品的"规则"。</b>所有判断集中在 <code>policy.config.json</code>，改这里立即生效、不需要发版；每次修改都会记入下方变更记录。带 🔒 的项需要技术与业务双签后才能改。</div></div>
${grp('AI 什么时候可以自己回','置信度越高越保守。阈值和追问区间共同决定"AI 直答 / 先追问 / 转人工"三档。',
  `${row('autoReply.threshold',policyReplay())}${row('autoReply.askBand')}${row('autoReply.maxAskRounds')}${row('autoReply.noMatchCap')}`)}
${grp('任何时候都不让 AI 自己回的事','这几条不受置信度影响。关掉开关等于允许 AI 直接对客承诺，请谨慎。',
  ['safety','refund','negative','b2b'].map(k=>`<div class="check"><div style="flex:1"><b>${Policy.label('hardRules.'+k)}</b><div class="muted small">${(Policy.def('hardRules.'+k)||{})._依据||''}</div></div>${sw(Policy.get('hardRules.'+k),`policySet('hardRules.${k}',${!Policy.get('hardRules.'+k)})`)}</div>`).join(''))}
${grp('触发词表 · 什么话会被判成硬规则','来信里出现这些词，就按上面的规则处理。安全件分两段：伤害描述锁定（删改需双签），零件名可随产品线增删。','')}${hardRuleWordsPanel()}
${grp('AI 可以主动承诺什么','金额、库存、地址都来自数据库，模型不能提供。超过上限的一律等人点确认。',
  `${row('shipping.autoCommitLimitUsd')}<div class="check"><div style="flex:1"><b>${Policy.label('shipping.smallParts')}</b><div class="muted small">${(Policy.def('shipping.smallParts')||{})._依据||''}</div></div>${sw(Policy.get('shipping.smallParts'),`policySet('shipping.smallParts',${!Policy.get('shipping.smallParts')})`)}</div><div class="check"><div style="flex:1"><b>${Policy.label('shipping.bigParts')}</b> 🔒<div class="muted small">${(Policy.def('shipping.bigParts')||{})._依据||''}</div></div>${sw(Policy.get('shipping.bigParts'),'toast(\'此项已锁定：需技术与业务双签，请在 config 文件里修改后重新发布\')')}</div><div class="check"><div style="flex:1"><b>${Policy.label('shipping.videos')}</b><div class="muted small">${(Policy.def('shipping.videos')||{})._依据||''}</div></div>${sw(Policy.get('shipping.videos'),`policySet('shipping.videos',${!Policy.get('shipping.videos')})`)}</div>${row('shipping.requireTrackingWithinHours')}`)}
${grp('流程护栏','影响工单怎么合并、怎么拆、怎么催，不影响对客措辞。',
  `${row('guard.mergeReopenDays')}${row('guard.repairGuideDays')}${row('guard.batchCluster.minSame')}${row('guard.batchCluster.ratio')}${row('guard.maxIssuesPerTicket')}${row('guard.maxReplyWords')}`)}
<div class="row" style="margin-top:6px"><span class="muted small">政策版本 ${Policy.version()}${diffs.length?` · 当前有 ${diffs.length} 项与出厂值不同`:' · 全部为出厂值'}</span><div class="sp"></div>${diffs.length?'<button class="btn sm" onclick="policyReset()">全部恢复出厂值</button>':''}<a class="btn sm ghost" onclick="download('policy_变更记录.json',JSON.stringify(Policy.log(),null,2),'application/json')">导出变更记录</a></div>
<div class="field" style="margin-top:16px"><label>变更记录（最近 12 条）</label>
${logRows.length?`<table class="tb"><tr><th>时间</th><th>谁</th><th>项</th><th>从</th><th>到</th></tr>${logRows.map(l=>`<tr><td class="muted small">${fmt(l.at)}</td><td>${esc(l.who)}</td><td>${esc(l.label)}</td><td class="num muted">${esc(String(l.from))}</td><td class="num"><b>${esc(String(l.to))}</b></td></tr>`).join('')}</table>`:'<div class="muted small">还没有改动过任何政策。</div>'}</div>`;
}
// 触发词表面板：每条规则显示 近 30 天命中数 / 命中过的词 / 样例句 / 可增删的词
function hardRuleWordsPanel(){
  const since=Date.now()-30*DAY; const all=state.tickets.filter(t=>t.createdAt>since);
  const ruleMeta={ safety:['安全件','safety'], refund:['退换货 / 赔偿','refund'], negative:['负面情绪 / 公开渠道','negative'], b2b:['企业邮箱判定（免费邮箱白名单）','b2b'] };
  const samples=(key)=>all.filter(t=>t.reasons.includes(key)).slice(-3).map(t=>{
    const r=(t.reasons||[]); const words=[];
    const txt=(t.timeline.find(e=>e.who==='cust')||{}).text||t.issue||'';
    if(typeof Policy!=='undefined'&&Policy.hitWords) words.push(...Policy.hitWords(key==='b2b'?'b2b':key,txt));
    return {id:t.id,issue:t.issue||'',words:[...new Set(words)].slice(0,6)};
  });
  const chip=(rule,kind,w,locked)=>`<span class="wchip${locked?' locked':' editable'}" title="${locked?'锁定词：删改需双签':'点击删除'}" ${locked?'':`onclick="policyRemoveWord('${rule}','${kind}','${escAttr(w)}')"`}>${esc(w)}${locked?'<i class="wl">🔒</i>':'<i class="wx">×</i>'}</span>`;
  const escAttr=(s)=>String(s).replace(/'/g,'\\\'');
  const oneRule=(key,label)=>{
    const hits=all.filter(t=>t.reasons.includes(key)); const ss=samples(key);
    const off = Policy.get('hardRules.'+key)===false;
    const top={}; for(const t of hits){ for(const w of (Policy.hitWords?Policy.hitWords(key==='b2b'?'b2b':key,t.issue||''):[])) top[w]=(top[w]||0)+1; }
    const topWords=Object.entries(top).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([w,n])=>`<span class="tag grey">${esc(w)} ${n}</span>`).join(' ');
    return `<div class="card" style="border:1px solid var(--line);border-radius:8px;padding:12px 14px;margin-bottom:10px">
      <div class="wrow"><b>${label}</b>${off?'<span class="tag grey">规则当前关闭</span>':''}<span class="tag ${hits.length&&!off?'amber':'grey'}">近 30 天触发 ${hits.length} 次</span></div>
      ${topWords?`<div class="wline"><span class="muted small">命中最多</span><span class="wchips">${topWords}</span></div>`:''}
      ${ss.length?`<div class="wsample"><div class="muted small">样例句</div>${ss.map(x=>`<div class="wsample-i"><span class="wsample-t">「${esc((x.issue||'').slice(0,70))}」</span>${x.words.length?`<span class="tag grey">${x.words.slice(0,4).join(' · ')}</span>`:''}</div>`).join('')}</div>`:'<div class="muted small" style="margin-top:6px">近 30 天没有触发。</div>'}
      <div class="wblock">${wordChips(key)}</div>
      <div class="wadd"><input class="input" id="w_${key}" placeholder="新增一个词，回车添加" onkeydown="if(event.key==='Enter')policyAddWord('${key}')"><button class="btn sm" onclick="policyAddWord('${key}')">添加</button></div>
    </div>`;
  };
  const wordChips=(key)=>{
    if(key==='safety'){
      const w=Policy.words('safety');
      return `<div class="wgroup"><div class="wlabel">伤害描述 <span class="tag grey">锁定 · 删改需双签</span></div><div class="wchips">${w.locked.map(x=>chip('safety','injury',x,true)).join('')}</div></div>
              <div class="wgroup"><div class="wlabel">安全部件名 <span class="tag grey">随产品线增删</span></div><div class="wchips">${w.editable.map(x=>chip('safety','parts',x,false)).join('')||'<span class="muted small">（空）</span>'}</div></div>`;
    }
    const w=Policy.words(key).all;
    return `<div class="wchips">${w.map(x=>chip(key,'',x,false)).join('')||'<span class="muted small">（空）</span>'}</div>`;
  };
  return Object.entries(ruleMeta).map(([k,lab])=>oneRule(k,lab[0])).join('');
}
function policyAddWord(rule){ const inp=document.getElementById('w_'+rule); const v=(inp&&inp.value||'').trim(); try{ const kind=rule==='safety'?'parts':''; Policy.addWord(rule,kind,v); save(); render(); toast(`已加入「${v}」`); }catch(e){ toast(e.message); } }
function policyRemoveWord(rule,kind,w){ try{ Policy.removeWord(rule,kind||'',w); save(); render(); toast(`已删除「${w}」`); }catch(e){ toast(e.message); } }
function policyRow(path,extra){
  const d=Policy.def(path)||{}; const cur=Policy.get(path); const isNum=typeof d.value==='number';
  const input=isNum
    ? `<input class="input num" type="number" value="${cur}" min="${d.min??''}" max="${d.max??''}" style="width:90px" onchange="policySet('${path}',this.value)"><span class="muted small">${d.unit||''}${d.min!=null?` · 可设 ${d.min}–${d.max}`:''}</span>`
    : `<input class="input" value="${esc(String(cur))}" style="width:220px" onchange="policySet('${path}',this.value)">`;
  const changed=cur!==d.value;
  return `<div class="check" style="align-items:flex-start"><div style="flex:1"><b>${esc(d.label||path)}</b>${d.locked?' 🔒':''}${changed?` <span class="tag amber">已改（出厂 ${esc(String(d.value))}${d.unit||''}）</span>`:''}<div class="muted small">${esc(d._依据||d._技术约束||'')}</div></div><div class="row">${input}${changed?`<button class="btn sm ghost" onclick="policyReset('${path}')">恢复</button>`:''}</div></div>${extra||''}`;
}
function addMailbox(){ const a=$('#mb_addr').value.trim(); if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(a)){ toast('请输入有效邮箱'); return; } state.settings.mailboxes.push({addr:a,provider:$('#mb_prov').value.split(' /')[0],connectedAt:Date.now(),imported:0}); save(); render(); toast(`${a} 已授权接入，开始同步`); }
function toggleNotify(c){ const i=state.settings.notify.indexOf(c); if(i>=0) state.settings.notify.splice(i,1); else state.settings.notify.push(c); save(); render(); }
function toggleH5Lang(k){ const i=state.settings.h5Langs.indexOf(k); if(i>=0) state.settings.h5Langs.splice(i,1); else state.settings.h5Langs.push(k); save(); render(); }
